@MainActor func transient_PackagePad_objectDisplay (
       _ self_xCenter : CanariLength,               
       _ self_yCenter : CanariLength,               
       _ self_width : CanariLength,                 
       _ self_height : CanariLength,                
       _ self_holeWidth : CanariLength,             
       _ self_holeHeight : CanariLength,            
       _ self_padShape : PadShape,                  
       _ self_padStyle : PadStyle,                  
       _ prefs_frontSidePadColor : NSColor,         
       _ prefs_displayPackageFrontSidePads : Bool,  
       _ prefs_backSidePadColor : NSColor,          
       _ prefs_displayPackageBackSidePads : Bool
) -> EBShape {
//--- START OF USER ZONE 2
    var bp = BezierPath.pad (
      centerX: self_xCenter,
      centerY: self_yCenter,
      width: self_width,
      height: self_height,
      shape: self_padShape
    )
    switch self_padStyle {
    case .traversing :
      var shape = EBShape (filled: [bp], .clear)
      let xCenter = self_xCenter
      let yCenter = self_yCenter
      let holeWidth = self_holeWidth
      let holeHeight = self_holeHeight
      let rHole = CanariRect (left: xCenter - holeWidth / 2.0, bottom: yCenter - holeHeight / 2.0, width: holeWidth, height: holeHeight)
      bp.appendOblong (in: rHole)
      bp.windingRule = .evenOdd
      if prefs_displayPackageFrontSidePads {
        shape.add (filled: [bp], prefs_frontSidePadColor)
        return shape
      }else if prefs_displayPackageBackSidePads {
        shape.add (filled: [bp], prefs_backSidePadColor)
        return shape
      }else{
        return EBShape ()
      }
    case .surface :
      if prefs_displayPackageFrontSidePads {
        return EBShape (filled: [bp], prefs_frontSidePadColor)
      }else{
        return EBShape ()
      }
    }
//--- END OF USER ZONE 2
}

